/**
 * Navigation per role, from the grants the backend really gives (`role-permissions.json` is
 * generated by `backend/scripts/role_matrix.py` and checked by a backend contract test).
 * Hiding an item is cosmetic; these tests keep what each role sees matching
 * docs/roles-and-permissions.md §3.
 */
import { describe, expect, it } from "vitest";

import { ME } from "../test/fakeApi";
import grants from "../test/role-permissions.json";
import { visibleNavItems } from "./navigation";
import type { Me } from "./session";

type RoleKey = keyof typeof grants;

function holding(...roles: RoleKey[]): Me {
  const permissions = new Set<string>(grants.account_baseline);
  for (const role of roles) grants[role].forEach((key) => permissions.add(key));
  return { ...ME, roles: roles.filter((role) => role !== "account_baseline"), permissions: [...permissions] };
}

function labels(me: Me): string[] {
  return visibleNavItems(me).map((item) => item.label);
}

const EMPLOYEE = [
  "Dashboard",
  "My attendance",
  "My leave",
  "Holidays",
  "Documents",
  "My profile",
  "Account security",
  "Directory",
  "Organization",
];

describe("navigation by role", () => {
  it("shows an employee only self-service and the directory", () => {
    expect(labels(holding("employee"))).toEqual(EMPLOYEE);
  });

  it("adds the team pages for a manager, without HR set-up or administration", () => {
    expect(labels(holding("employee", "manager"))).toEqual([
      "Dashboard",
      "My attendance",
      "My leave",
      "Holidays",
      "Documents",
      "My profile",
      "Account security",
      "Team attendance",
      "Attendance corrections",
      "Leave approvals",
      "Leave calendar",
      "Employees",
      "Directory",
      "Organization",
      "Reports",
    ]);
  });

  it("gives HR the organization-wide pages and shift assignment, but no configuration", () => {
    expect(labels(holding("hr"))).toEqual([
      "Dashboard",
      "Holidays",
      "Documents",
      "Account security",
      "Team attendance",
      "Attendance corrections",
      "Location reviews",
      "Leave approvals",
      "Leave calendar",
      "Employees",
      "Former employees",
      "Organization",
      "Leave overview",
      "Leave balances",
      "Reports",
      "Attendance set-up",
      "Users",
    ]);
  });

  it("adds HR configuration, roles and settings for an HR admin", () => {
    expect(labels(holding("hr_admin"))).toEqual([
      "Dashboard",
      "Holidays",
      "Documents",
      "Account security",
      "Team attendance",
      "Attendance corrections",
      "Location reviews",
      "Leave approvals",
      "Leave calendar",
      "Employees",
      "Former employees",
      "Organization",
      "Leave overview",
      "Leave balances",
      "Reports",
      "Holiday calendars",
      "Leave types",
      "Attendance set-up",
      "Document categories",
      "Users",
      "Roles",
      "Access requests",
      "Settings",
    ]);
  });

  it("keeps a system admin to accounts, security and settings, with no HR data", () => {
    expect(labels(holding("system_admin"))).toEqual([
      "Dashboard",
      "Account security",
      "Users",
      "Roles",
      "Access requests",
      "Security events",
      "Settings",
    ]);
  });

  it("keeps a super admin to access governance, data erasure and the audit log, with no HR data", () => {
    expect(labels(holding("super_admin"))).toEqual([
      "Dashboard",
      "Account security",
      "Users",
      "Roles",
      "Access requests",
      "Data erasure",
      "Security events",
      "Audit log",
      "Settings",
    ]);
  });

  it("gives a super admin linked to their own record self-service, and no team pages", () => {
    // The API never derives the manager role for a super admin (owner decision 2026-10-23).
    const shown = labels(holding("employee", "super_admin"));
    for (const label of EMPLOYEE) expect(shown).toContain(label);
    expect(shown).not.toContain("Team attendance");
    expect(shown).not.toContain("Employees");
  });

  it("gives an HR person linked to an employee record their own self-service too", () => {
    const shown = labels(holding("employee", "hr"));
    for (const label of EMPLOYEE) expect(shown).toContain(label);
    expect(shown).not.toContain("Leave types");
  });
});
